import{_ as a,o as i,c as t,an as n}from"./chunks/framework.DHlhpxdU.js";const g=JSON.parse('{"title":"MedImages.jl Experiments","description":"","frontmatter":{},"headers":[],"relativePath":"experiments/index.md","filePath":"experiments/index.md","lastUpdated":null}'),l={name:"experiments/index.md"};function r(s,e,o,d,c,m){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="MedImages.jl-Experiments" tabindex="-1">MedImages.jl Experiments <a class="header-anchor" href="#MedImages.jl-Experiments" aria-label="Permalink to &quot;MedImages.jl Experiments {#MedImages.jl-Experiments}&quot;">​</a></h1><p>This section details the experiments conducted to evaluate the MedImages.jl framework against four core challenges in modern quantitative medical imaging. These challenges are detailed in our PLOS Computational Biology manuscript.</p><h2 id="Overview-of-Challenges" tabindex="-1">Overview of Challenges <a class="header-anchor" href="#Overview-of-Challenges" aria-label="Permalink to &quot;Overview of Challenges {#Overview-of-Challenges}&quot;">​</a></h2><ol start="2"><li><strong>Challenge 1: Volume – Scaling to 100 Cases (HDF5 vs. Caching)</strong> Processing large biobank-scale datasets creates significant I/O and transform bottlenecks. We benchmarked a 100-case multimodal preprocessing pipeline against established caching mechanisms.</li></ol><ul><li><a href="./volume_scaling">Read the Volume Scaling Experiment Details</a></li></ul><ol start="3"><li><strong>Challenge 2: Speed – GPU Acceleration Benchmarks</strong> Execution speed of basic spatial filters limits rapid prototyping. We evaluated native Julia GPU acceleration against classical C++ (SimpleITK) CPU baselines for resampling and affine transformations.</li></ol><ul><li><a href="./gpu_acceleration">Read the GPU Acceleration Experiment Details</a></li></ul><ol start="4"><li><strong>Challenge 3: Differentiability and SciML Validation</strong> Emerging Scientific Machine Learning (SciML) paradigms require fully differentiable pipelines. We validated this through two complex setups:</li></ol><ul><li><p><a href="./learned_inverse_rotation">Learned Inverse Rotation (Geometric CNN)</a>: Training a network to predict and invert 3D rotations by differentiating through the spatial resampling grid.</p></li><li><p><a href="./dosimetry_ude">Quantitative Dosimetry via Universal Differential Equations (UDE)</a>: A hybrid physics-neural network model to predict high-fidelity radiation dose maps, integrating spatial gradients and tissue densities.</p></li></ul><ol start="5"><li><strong>Challenge 4: Metadata Management and Clinical Fidelity</strong> To avoid &quot;metadata drift&quot; during preprocessing, spatial and temporal clinical context must remain bound to the voxel array. We evaluated how our framework strictly preserves these attributes.</li></ol><ul><li><a href="./metadata_fidelity">Read the Metadata Fidelity Experiment Details</a></li></ul>',11)])])}const h=a(l,[["render",r]]);export{g as __pageData,h as default};
